#include "qcae/task_service.hpp"
#include <cstring>
struct BinaryRead {
 std::string_view source; std::size_t pos{};
 std::uint64_t integer(){demand(source.size()-pos>=8,"u64 framing");std::uint64_t n{};for(unsigned i=0;i<8;++i)n|=std::uint64_t(static_cast<unsigned char>(source[pos++]))<<(8*i);return n;}
 std::string text(){auto n=integer();demand(n<=source.size()-pos,"text framing");auto value=std::string(source.substr(pos,n));pos+=n;return value;}
};
void u64(std::string& out,std::uint64_t n){for(unsigned i=0;i<8;++i)out.push_back(static_cast<char>(n>>(8*i)));}
void text8(std::string& out,std::string_view text){u64(out,text.size());out.append(text);}
std::shared_ptr<const OwnedRowImage> read_image(std::uint64_t space,std::string id,std::string bytes){BinaryRead r{bytes};demand(r.text()=="QCAE-OWNED-ROW"&&r.integer()==1,"owned envelope");auto owner=r.text();auto schema=r.integer();auto payload=r.text();demand(r.pos==bytes.size(),"owned trailing");return std::make_shared<const OwnedRowImage>(OwnedRowImage{{static_cast<StoreSpace>(space),std::move(id)},std::move(owner),static_cast<std::uint32_t>(schema),std::make_shared<const std::string>(std::move(payload)),{}});}
std::string image_bytes(const OwnedRowImage& image){std::string out;text8(out,"QCAE-OWNED-ROW");u64(out,1);text8(out,image.owner);u64(out,image.schema_version);text8(out,*image.payload);return out;}
